  pair.detection = replacePowerShellAssignment(pair.detection, 'InstallIfMissing', installLiteral);
  pair.remediation = replacePowerShellAssignment(pair.remediation, 'InstallIfMissing', installLiteral);
  pair.detection = replacePowerShellAssignment(pair.detection, 'FallbackLatestVersion', fallbackLiteral);
  pair.remediation = replacePowerShellAssignment(pair.remediation, 'FallbackLatestVersion', fallbackLiteral);
